/** 分類器は  だけを読む。 を通さない綴りまで当てるため、その形の物を渡す。 */
const asUrl = (hostname: string): URL => ({ hostname }) as unknown as URL;

describe('privateTarget — 分岐の表 (移す前の実装から取った期待値)', () => {
  it('★ 表は private と public の両方を十分に含む (どちらかに偏った表は空の検査になる)', () => {
    const priv = HOSTS.filter(([, v]) => v).length;
    expect(priv).toBeGreaterThan(900);
    expect(HOSTS.length - priv).toBeGreaterThan(700);
  });

  it.each(HOSTS)('%s → %s', (host, expected) => {
    expect(isPrivateOrReservedTarget(asUrl(host))).toBe(expected);
  });

  it.each(EXPAND)('expandV6Groups(%s)', (input, expected) => {
    expect(expandV6Groups(input)).toEqual(expected);
  });

  it.each(NON_GLOBAL)('isNonGloballyReachableV6(%s) → %s', (input, expected) => {
    expect(isNonGloballyReachableV6(input)).toBe(expected);
  });

  it('★ 実物の URL を通した形でも同じ答え (URL が正規化した後の綴り)', () => {
    const real: ReadonlyArray<readonly [string, boolean]> = [
      ['http://[::ffff:127.0.0.1]/', true],
      ['http://[::ffff:8.8.8.8]/', false],
      ['http://[::169.254.169.254]/', true],
      ['http://[::ffff:0:127.0.0.1]/', true],
      ['http://[64:ff9b::7f00:1]/', true],
      ['http://[64:ff9b::808:808]/', false],
      ['http://[2002:7f00::1]/', true],
      ['http://[2002::]/', true],
      ['http://[2002:808:808::]/', false],
      ['http://[2606:4700::1111]/', false],
      ['http://[fe80::1]/', true],
      ['http://localhost./', true],
      ['http://0177.0.0.1/', true],
      ['http://2130706433/', true],
      ['http://example.com/', false],
    ];
    for (const [u, expected] of real) {
      expect(isPrivateOrReservedTarget(new URL(u))).toBe(expected);
    }
  });
});
